"use strict";(self.webpackChunkhalt_website=self.webpackChunkhalt_website||[]).push([[60553],{717:e=>{e.exports=JSON.parse('{"tag":{"label":"Animal Welfare","permalink":"/docs/tags/animal-welfare","allTagsPath":"/docs/tags","count":1,"items":[{"id":"general-care/sensitive-topics/animal-hoarding","title":"The Shadow of Compassion: Understanding and Addressing Animal Hoarding","description":"Animal hoarding is a complex and tragic issue that sits at the intersection of animal welfare, public health, and mental illness. It is not born from a place of malice, but often from a deeply misguided sense of love and a compulsive need to \u201csave\u201d animals. This article aims to shed light on this sensitive topic with the delicacy it deserves, providing guidance for individuals who may be struggling, as well as for rescues navigating these difficult situations.","permalink":"/docs/general-care/sensitive-topics/animal-hoarding"}],"unlisted":false}}')}}]);